using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Sigov.Api.Middlewares; using Sigov.Application.Agro.FeirasMercados; using Sigov.Application.Common; using Sigov.Domain.Common;
namespace Sigov.Api.Controllers;
[ApiController,Authorize,RequireModule("agro")] public sealed class AgroFeirasController:ControllerBase{private readonly IAgroFeiraService _f; private readonly IAgroFeiranteService _fe; public AgroFeirasController(IAgroFeiraService f,IAgroFeiranteService fe){_f=f;_fe=fe;} [HttpGet("api/agro/feiras")] public async Task<ActionResult<ApiResponse<PagedResult<AgroFeiraResponse>>>> Feiras(int page=1,int pageSize=20,CancellationToken ct=default)=>FromResult(await _f.ListarAsync(page,pageSize,ct)); [HttpGet("api/agro/feiras/{id:long}")] public async Task<ActionResult<ApiResponse<AgroFeiraResponse>>> Feira(long id,CancellationToken ct)=>FromResult(await _f.ObterAsync(id,ct)); [HttpPost("api/agro/feiras")] public async Task<ActionResult<ApiResponse<long>>> CriarFeira([FromBody]AgroFeiraCreateRequest r,CancellationToken ct)=>FromResult(await _f.CriarAsync(r,ct)); [HttpPut("api/agro/feiras/{id:long}")] public async Task<ActionResult<ApiResponse<object>>> AtualizarFeira(long id,[FromBody]AgroFeiraCreateRequest r,CancellationToken ct)=>FromResult(await _f.AtualizarAsync(id,r,ct)); [HttpDelete("api/agro/feiras/{id:long}")] public async Task<ActionResult<ApiResponse<object>>> ExcluirFeira(long id,CancellationToken ct)=>FromResult(await _f.ExcluirAsync(id,ct)); [HttpGet("api/agro/feirantes")] public async Task<ActionResult<ApiResponse<PagedResult<AgroFeiranteResponse>>>> Feirantes(int page=1,int pageSize=20,CancellationToken ct=default)=>FromResult(await _fe.ListarAsync(page,pageSize,ct)); [HttpPost("api/agro/feiras/{id:long}/feirantes")] public async Task<ActionResult<ApiResponse<long>>> CriarFeirante(long id,[FromBody]AgroFeiranteCreateRequest r,CancellationToken ct)=>FromResult(await _fe.CriarAsync(id,r,ct)); [HttpPut("api/agro/feirantes/{id:long}")] public async Task<ActionResult<ApiResponse<object>>> AtualizarFeirante(long id,[FromBody]AgroFeiranteCreateRequest r,CancellationToken ct)=>FromResult(await _fe.AtualizarAsync(id,r,ct)); [HttpPost("api/agro/feirantes/{id:long}/autorizar")] public async Task<ActionResult<ApiResponse<object>>> Autorizar(long id,CancellationToken ct)=>FromResult(await _fe.AutorizarAsync(id,ct)); [HttpPost("api/agro/feirantes/{id:long}/suspender")] public async Task<ActionResult<ApiResponse<object>>> Suspender(long id,CancellationToken ct)=>FromResult(await _fe.SuspenderAsync(id,ct)); [HttpGet("api/agro/feiras/{id:long}/bancas")] public async Task<ActionResult<ApiResponse<PagedResult<AgroBancaFeiraResponse>>>> Bancas(long id,CancellationToken ct)=>FromResult(await _fe.ListarBancasAsync(id,ct)); [HttpPost("api/agro/feiras/{id:long}/bancas")] public async Task<ActionResult<ApiResponse<long>>> CriarBanca(long id,[FromBody]AgroBancaFeiraCreateRequest r,CancellationToken ct)=>FromResult(await _fe.CriarBancaAsync(id,r,ct)); private ActionResult<ApiResponse<T>> FromResult<T>(Result<T> r){if(r.IsSuccess&&r.Value is not null)return Ok(ApiResponse<T>.Ok(r.Value)); if(r.Error=="403")return Forbid(); if(r.Error?.Contains("autenticado",StringComparison.OrdinalIgnoreCase)==true)return Unauthorized(ApiResponse<T>.Fail(r.Error)); return UnprocessableEntity(ApiResponse<T>.Fail(r.Error??"Requisição inválida."));} private ActionResult<ApiResponse<object>> FromResult(Result r){if(r.IsSuccess)return Ok(ApiResponse<object>.Ok(new{ok=true})); if(r.Error=="403")return Forbid(); return UnprocessableEntity(ApiResponse<object>.Fail(r.Error??"Requisição inválida."));}}
